const prSW = {}
onmessage = ev => {
	const data = ev.data
	if ('sw' in data && 'cache' in data.sw) {
		if (data.sw?.set && data.sw?.lang) {
			const name = `${data.sw?.set}-${data.sw?.lang}`
			prSW[name]?.resolve(data.sw.cache)
		}
	}
}
(async () => {
	const exts = await fetch('db/img-exts.json', { cache: 'no-cache' }).then(res => res.json())
	for (const ext of exts) {
		let _resolve
		const name = `${ext.name}-${ext.lang}`
		prSW[name] = new Promise(resolve => {
			_resolve = keys => {
				const res = { total: ext.total, remaining: ext.total - Object.keys(keys).length, set: ext.name, lang: ext.lang }
				resolve(res)
			}
		})
		prSW[name].resolve = _resolve
		postMessage({ sw: { getCache: { set: ext.name, lang: ext.lang } } })
	}
	Promise.all(Object.values(prSW)).then((results, i) => {
		const { total, remaining, sets } = results.reduce((o, { total, remaining, set, lang }) => {
			o.total += total
			o.remaining += remaining
			if (remaining) o.sets.push(`${set}:${lang}`)
			return o
		}, { total: 0, remaining: 0, sets: [] })
		postMessage({ resolve: { total, remaining, sets } })
	})
})()